import{z as s,x as l,o as n,c as m,q as p,j as c,D as t,d as e,s as r,S as E,b as o}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"页迁移与 compaction","description":"","frontmatter":{"title":"页迁移与 compaction","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/page-migration-compaction.md","filePath":"cs/page-migration-compaction.md","lastUpdated":1791063341000}'),d={name:"cs/page-migration-compaction.md"};function A(B,a,f,h,u,g){const i=l("Mermaid");return n(),m("div",null,[a[2]||(a[2]=p('<h1 id="页迁移与-compaction" tabindex="-1">页迁移与 compaction <a class="header-anchor" href="#页迁移与-compaction" aria-label="Permalink to &quot;页迁移与 compaction&quot;">​</a></h1><div class="epigraph"><p>迁移把页内容拷到新页框并改所有 pte；compaction 在区内把可移页往一端赶，以便拼出连续高阶块。</p><footer>—— 据 Linux 对 page migration 与 compaction 的文档；Gorman 对反碎片的讨论</footer></div><p><a href="/cs/rmap">上一课</a>能改所有映射。<a href="/cs/buddy-allocator">buddy</a> 在碎片化后交不出 2^n 大块，<a href="/cs/thp">THP</a> 与 DMA 会失败。缺口是 <strong>迁移 + compaction</strong>：不是用户 <code>mremap</code> 的百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不可移页（内核 pinned、部分驱动）挡在中间。compaction：扫描 zone，隔离可移页，迁移到另一端，腾出连续空闲。NUMA：<code>migratepages</code> 把页挪到目标节点。缺口：失败回退、延迟（一次 compact 可停很久）、与 <a href="/cs/memcg">cgroup</a> 回收的交织。本课不把每条 isolate 函数当课纲。</p><p><span class="marginnote">同步 compact 发生在高阶分配失败路径；kcompactd 后台做。CMA 为连续分配预留，是亲戚。</span></p><p><span class="marginnote">pinned（钉住）就是有人把这页「钉」在原地不许搬：典型是 DMA——设备正往这个物理地址直写数据，内核要是偷偷把页搬走，设备下一笔就写进别人的页里了。所以迁移前必须确认没有这类钉子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>migrate_pages</code>：分配目标页，拷内容，rmap 换 pte，释放源。compaction：把迁移当原语，循环直到出现足够空闲阶。对照 <a href="/cs/bcache">bcache</a>：一个搬存储块，一个搬内存页。对照 FS <a href="/cs/ext4-extents">extent</a>：都在对付碎片，介质不同。</p>',9)),(n(),c(E,null,{default:t(()=>[r(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FRAG%5B%22%E7%A9%BA%E9%97%B2%E7%A2%8E%E7%89%87%22%5D%20--%3E%20ISO%5B%22%E9%9A%94%E7%A6%BB%E5%8F%AF%E7%A7%BB%E9%A1%B5%22%5D%0A%20%20ISO%20--%3E%20MIG%5B%22%E8%BF%81%E7%A7%BB%E5%88%B0%E6%96%B0%E6%A1%86%22%5D%0A%20%20MIG%20--%3E%20BUDDY%5B%22buddy%20%E5%90%88%E5%B9%B6%E9%AB%98%E9%98%B6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("compaction 用迁移换连续物理内存，使大页与某些驱动继续可行。它改变 pfn，不改变用户虚址。不要写成磁盘碎片整理产品。与 "),o("a",{href:"/cs/fsync"},"fsync"),e(" 无关——页在 RAM。")],-1)),a[5]||(a[5]=o("p",null,[o("span",{class:"marginnote"},"「改 pfn、不改虚址」可以想象成小区整体搬迁：住户（进程）手里的门牌号（虚拟地址）一个字没变，物业只是把家具（页内容）搬进新楼，并悄悄改了自己手里的地址簿（页表）。所以迁移对用户程序完全透明。")],-1)),a[6]||(a[6]=o("p",null,"单页迁移本身的五步是：确认可移 → 分配新框 → 拷内容 → 经 rmap 改所有 pte → 释放旧框；任何一步卡住，本轮就放弃。",-1)),(n(),c(E,null,{default:t(()=>[r(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%A6%81%E8%BF%81%E7%A7%BB%E4%B8%80%E9%A1%B5%22%5D%20--%3E%20PIN%7B%22%E9%A1%B5%E8%A2%AB%20pinned%3F%22%7D%0A%20%20PIN%20--%3E%7C%22%E6%98%AF%22%7C%20GIVEUP%5B%22%E6%9C%AC%E8%BD%AE%E6%94%BE%E5%BC%83%20%E5%9B%9E%E9%80%80%22%5D%0A%20%20PIN%20--%3E%7C%22%E5%90%A6%22%7C%20ALLOC%5B%22%E5%88%86%E9%85%8D%E6%96%B0%E9%A1%B5%E6%A1%86%22%5D%0A%20%20ALLOC%20--%3E%20COPY%5B%22%E6%8B%B7%E8%B4%9D%E9%A1%B5%E5%86%85%E5%AE%B9%22%5D%0A%20%20COPY%20--%3E%20PTE%5B%22rmap%20%E6%89%BE%E6%89%80%E6%9C%89%E6%98%A0%E5%B0%84%20%E9%80%90%E4%B8%AA%E6%94%B9%20pte%22%5D%0A%20%20PTE%20--%3E%20FREE%5B%22%E9%87%8A%E6%94%BE%E6%97%A7%E9%A1%B5%E6%A1%86%22%5D%0A%20%20FREE%20--%3E%20DONE%5B%22%E8%99%9A%E5%9C%B0%E5%9D%80%E4%B8%8D%E5%8F%98%20%E7%89%A9%E7%90%86%E4%BD%8D%E7%BD%AE%E5%B7%B2%E6%8D%A2%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=p('<p>延迟：直接回收+compact 是分配延迟的来源之一，后课 memcg 限制会更频繁触发。</p><p><span class="marginnote">为什么重要：一次同步 compact 可能扫完整个 zone 才肯罢手，毫秒级停顿就这么来的。若放在音频线程或网络收包路径里触发，表现出来就是「偶发卡顿、抓不到凶手」——这也是数据库和低延迟服务要预留大页、关掉直接 compact 的原因。</span></p><p>实现上：隔离页失败则 compact 放弃这一轮，高阶分配走回退阶。CMA 与迁移共用可移性，驱动 pin 会让 CMA 分配失败。跨 NUMA 迁移要更新页的 nid 与统计。 读法上只引用<a href="/cs/rmap">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>页迁移与 compaction</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 memory compaction 的全部 sysctl。不保证实时系统能忍受 kcompactd。下一课消费者：透明大页。</p><p>版本字段会变，课序钉的是机制对象「页迁移与 compaction」，不是某一主线内核的结构体名。 后课默认：内核可搬家以拼连续框。匿名/文件透明 2MB 页如何折叠，下一课 THP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>迁移改 pte 与内容所在 pfn。</li><li>compaction 用迁移反碎片，服务高阶分配。</li><li>THP 是下一课。</li><li>出处：Linux mm/migration、compaction；Gorman。</li></ul>',10))])}const C=s(d,[["render",A]]);export{P as __pageData,C as default};
